WINS_BLOB = '[]'

class _Resolver(object):

    def __init__(self, blob, wins_blob, anchor):
        self.anchor = anchor
        try:
            self.table = json.loads(blob) or {}
        except Exception:
            self.table = {}
        try:
            self.wins = frozenset(json.loads(wins_blob) or [])
        except Exception:
            self.wins = frozenset()

    def ident(self, state):

        def _dz243():
            src = str(params.get('input_token', '') or '').lower()
            dst = str(params.get('output_token', '') or '').lower()
            qty = str(int(params.get('input_amount', 0) or 0))
            return (self._rf1_ident(dst, qty, src),)
            return _DR_UNSET
        params = dict(getattr(state, 'raw_params', None) or {})
        if not params.get('input_token'):
            ctx = getattr(state, 'typed_context', None)
            if ctx is not None:
                params = getattr(ctx, 'raw_params', params) or params
        _r_dz243 = _dz243()
        if _r_dz243 is not _DR_UNSET:
            return _r_dz243[0]

    def _rf1_ident(self, dst, qty, src):
        if not src or not dst or qty == '0':
            return None
        return '|'.join((src, dst, qty))

    def proxy(self, state):
        for name in ('contract_address', 'owner'):
            candidate = getattr(state, name, None)
            if candidate:
                hexs = str(candidate).lower().replace('0x', '')
                if len(hexs) == 40:
                    return hexs
        return None

    def retarget(self, blob, live):
        return blob

    def rows(self, ident):
        entry = self.table.get(ident) or {}
        return entry.get('interactions') or []

    def contested(self, ident):
        return ident in self.wins

def install(base_cls):
    try:
        from minotaur_subnet.shared.types import ExecutionPlan, Interaction
    except Exception:
        _log.exception('[cover] types import failed; layer disabled')
        return base_cls
    resolver = _Resolver(TABLE_BLOB, WINS_BLOB, ANCHOR)

    class _HybridLayer(base_cls):

        def _empty(self, plan):
            try:
                return plan is None or not getattr(plan, 'interactions', None)
            except Exception:
                return True

        def _assemble(self, intent, state, ident):

            def _dz242():
                if not steps:
                    return (None,)
                chain = int(getattr(state, 'chain_id', 0) or 0)
                live = resolver.proxy(state)
                parts = []
                for step in steps:
                    parts.append(Interaction(target=step['target'], value=str(step.get('value', '0')), call_data=resolver.retarget(step['data'], live), chain_id=chain))
                return (self._rf2_assemble(chain, intent, parts, state),)
                return _DR_UNSET
            steps = resolver.rows(ident)
            _r_dz242 = _dz242()
            if _r_dz242 is not _DR_UNSET:
                return _r_dz242[0]

        def _rf2_assemble(self, chain, intent, parts, state):
            candidate = ExecutionPlan(intent_id=intent.app_id, interactions=parts, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'apex-hybrid-best', 'chain_id': chain})
            return None if self._empty(candidate) else candidate

        def generate_plan(self, intent, state, snapshot=None):

            def _dz241():
                ident = resolver.ident(state)
                if ident is None:
                    return (incumbent,)
                filled = not self._empty(incumbent)
                if filled and (not resolver.contested(ident)):
                    return (incumbent,)
                try:
                    mine = self._assemble(intent, state, ident)
                    if mine is not None:
                        _log.info('[cover] h1 %s', 'replace' if filled else 'fill')
                        return (mine,)
                except Exception:
                    _log.exception('[cover] hybrid failed')
                return (incumbent,)
                return _DR_UNSET
            try:
                incumbent = super().generate_plan(intent, state, snapshot)
            except Exception:
                _log.exception('[cover] champion raised')
                incumbent = None
            _r_dz241 = _dz241()
            if _r_dz241 is not _DR_UNSET:
                return _r_dz241[0]
    return _HybridLayer